//! HTTP header value and body constants for the conversion API.
//!
//! MIME type constants live in the sibling [`crate::mime`] module.

/// Cache-Control header value applied to all responses.
pub const CACHE_CONTROL_VALUE: &str = "max-age=0, private, must-revalidate";

/// Name of the trace-id request header, echoed back when present and never
/// generated by the server.
pub(crate) const X_TRACE_ID_HEADER: &str = "x-trace-id";

/// `Allow` header value for `/conversion`.
pub(crate) const ALLOW_CONVERSION: &str = "GET, HEAD, POST, OPTIONS";

/// `Allow` header value for `/health`.
pub(crate) const ALLOW_HEALTH: &str = "GET, HEAD, OPTIONS";

/// `Allow` header value for read-only resources such as `/openapi.json`.
pub(crate) const ALLOW_GET_HEAD: &str = "GET, HEAD";

/// `Content-Type` of the API catalog: an RFC 9264 linkset with the RFC 9727 profile.
pub(crate) const API_CATALOG_CONTENT_TYPE: &str =
    r#"application/linkset+json; profile="https://www.rfc-editor.org/info/rfc9727""#;

/// `Link` header value that points at the API catalog (RFC 9727 §2).
///
/// Sent only on the catalog's own responses, so the relative `api-catalog`
/// resolves to the catalog both at the origin root and under a path prefix.
pub(crate) const API_CATALOG_LINK: &str = r#"<api-catalog>; rel="api-catalog""#;

/// Health endpoint response body.
pub const HEALTH_BODY: &str = "Healthy.";
